import { selectSection } from './interface-workspaces.js';
import { renderEconomyPlan } from './economy-planning.js';
import { CAREER_SPECIALTIES } from './career-development.js';
import { getActions } from './engine.js';
import { careerView } from './careers.js';
import { healthView } from './health.js';
import { lineageView } from './lineage.js';
import { renderAvatar } from './avatar.js';
import { householdBudgetView, HOUSEHOLD_FOCI, HOUSEHOLD_LIFESTYLES, annualWorkRatio } from './budget.js';

const locationName = (game, id) => game.world.locations.find(place => place.id === id)?.name || id;
const living = person => person.alive !== false;

function actionList(ui, actions) {
  return actions.length ? ui.actionCards(actions) : '';
}

function offeredAction(ui, actions, id, label, style = 'primary') {
  const action = actions.find(item => item.id === id);
  if (!action) return '';
  const { e, button } = ui;
  const time = action.durationDays ? `${action.durationDays} days, with pauses` : action.days ? `${action.days} days` : 'No time cost';
  return `<div class="offered-action">${button(e(label || action.label), 'activity', action.id, style, !!action.disabledReason)}<small>${e(time)}${action.cost ? ` · ${e(action.cost)} gold` : ''}</small>${action.disabledReason ? `<p class="disabled-reason">${e(action.disabledReason)}</p>` : ''}${ui.livingCosts(action.durationDays||action.days)}</div>`;
}


function metric(ui, label, value) {
  return `<div><span>${ui.e(label)}</span><strong>${ui.e(value)}</strong></div>`;
}


export function householdBudgetPanel(game, ui) {
  const view=householdBudgetView(game);if(!view)return '';
  const {e,button,actionCards}=ui;
  const focus=HOUSEHOLD_FOCI.find(item=>item.id===view.focus), lifestyle=HOUSEHOLD_LIFESTYLES.find(item=>item.id===view.lifestyle);
  return `<section class="panel household-budget"><div class="eyebrow">TIME, CARE &amp; A HEARTH TO KEEP</div><h2>Your ordinary year</h2><p>${e(focus?.label||view.focus)} · ${e(lifestyle?.label||view.lifestyle)}</p><div class="career-stats">${metric(ui,'Living costs per year',`${view.annual}g`)}${metric(ui,'Accrued, unsettled',`${view.outstanding}g`)}${metric(ui,'Savings used',`${view.paid}g`)}${view.debt?metric(ui,'Owed',`${view.debt}g`):''}</div>${view.debt?`<p class="care-support">You owe ${e(view.debt)} gold. It grows a tenth each year, and at three years of living costs the lender will come for an answer.</p>`:''}<p class="small-copy muted">${e(view.description)}</p>${game.age<18?'<p class="care-support">Living costs and your own annual priorities begin at age 18.</p>':''}${view.supported?`<p class="care-support">Recorded budget shortfall: ${e(view.supported)} gold. Community care protects basic necessities; optional comforts are put aside when savings run short.</p>`:''}${view.actions.length?`<details class="construction-section household-priorities" data-disclosure="household-priorities"><summary>Choose priorities &amp; living standards</summary><h3>Where your time goes</h3>${actionCards(view.actions.filter(action=>action.id.startsWith('budget_focus_')))}<h3>How you keep your home</h3>${actionCards(view.actions.filter(action=>action.id.startsWith('budget_lifestyle_')))}</details>`:game.phase!=='retired'&&game.age>=18?'<p class="muted">Finish the current moment before changing your future priorities.</p>':''}</section>`;
}

/** A commitment is displayed even when a scene temporarily removes its actions. */
export function careerBatchPanel(game, ui) {
  const view = careerView(game), batch = view.batch;
  if (!batch) return '';
  const { e, meter, button } = ui;
  const actions = getActions(game).filter(action => ['career_batch_continue', 'career_batch_cancel'].includes(action.id));
  return `<section class="panel career-project career-batch-panel"><div class="eyebrow">${batch.kind === 'masterwork' ? 'A WORK TO LEAVE BEHIND' : 'A WORKING COMMITMENT'}</div><h2>${e(batch.title)}</h2><p>${e(locationName(game, batch.locationId))} · ${e(batch.profession)}</p>${meter(batch.completedDays, batch.totalDays, 'Working days completed')}<div class="career-stats">${metric(ui, 'Days remaining', batch.remainingDays)}${metric(ui, 'Days completed', batch.completedDays)}${metric(ui, 'Wages earned', `${batch.paidGold}g`)}</div><p>${batch.kind === 'masterwork' ? 'The supplies are committed. Each completed day brings the work closer to its final form.' : `The agreed wage is ${e(batch.wage)} gold per three completed working days. Your progress and earnings remain recorded when life interrupts.`}</p>${actions.length ? actionList(ui, actions) : `<p class="muted">Finish the waiting moment before returning to this work.</p>${button('Return to your life', 'tab', 'life', 'secondary')}`}</section>`;
}

export function careerPage(game, ui, options={}) {
  const view = careerView(game), { e, title, button, chapter, meter, historyList, materialNeeds, date } = ui;
  const actions = getActions(game), careerActions = actions.filter(action => action.id.startsWith('career_'));
  const progress = view.progress;
  const workActions = actions.filter(action => ['career_work', 'career_practice', 'career_batch_month', 'career_batch_year', 'life_promotion'].includes(action.id)||action.id.startsWith('career_specialty_'));
  const supplies = careerActions.filter(action => action.id.startsWith('career_buy_'));
  const businessActions = careerActions.filter(action => ['career_open_shop', 'career_shop_operate', 'career_shop_upgrade', 'career_hire', 'career_mentor'].includes(action.id));
  const currentTitle = view.profession.name === 'Unemployed' ? 'Flexible local labor' : view.profession.name;
  const summary = `<section class="panel career-summary"><div class="section-heading"><div><span class="eyebrow">YOUR LIVELIHOOD</span><h2>${e(currentTitle)}</h2></div><span class="badge career-rank">${e(progress.masteryLabel)}</span></div><p>${e(view.profession.description)}</p><div class="career-stats">${metric(ui, game.age < 16 ? 'Future shift wages' : 'Three-day wages', `${view.wages.shift}g`)}${metric(ui, 'Projected age-up income', game.phase === 'retired' ? 'Chapter closed' : game.age < 18 ? 'Age 18+' : `${Math.round(view.wages.annual*annualWorkRatio(game))}g / year`)}${metric(ui, 'Work recorded', `${progress.workedDays} days`)}</div>${progress.nextMastery ? meter(progress.experience, progress.nextMastery, 'Experience toward the next mastery') : `<div class="progress-label"><span>Mastery earned</span><strong>${e(progress.experience)} experience</strong></div>`}<div class="career-progress-pair">${meter(progress.reputation, 100, 'Professional reputation')}${meter(progress.safety, 100, 'Safe working practice')}</div><p class="small-copy muted">${progress.specialty?e(CAREER_SPECIALTIES[progress.specialty].name)+' · ':''}${e(progress.commissions)} commissions delivered · ${e(progress.earnedGold)} gold earned. Age up includes an ordinary mix of work and everyday life. This projection follows your current priorities, before living costs. A dedicated work commitment pays the agreed rate for each completed work day.</p>${game.age < 16 ? '<p class="care-support">Paid professions open at age 16. Childhood lessons and practice can prepare you for the work you choose.</p>' : ''}${actionList(ui, workActions)}</section>`;
  const professions = `<details class="construction-section profession-catalog" data-disclosure="professions" ${game.age >= 16 && view.profession.id === 'unemployed' && !view.batch ? 'open' : ''}><summary>Explore professions <span class="badge">${view.professions.length}</span></summary><div class="career-grid">${view.professions.map(job => `<article class="career-card ${job.id === view.profession.id ? 'current' : ''}"><span class="career-rank">${job.id === view.profession.id ? 'YOUR CURRENT WORK' : job.skill ? e(title(job.skill)) : 'FLEXIBLE LOCAL LABOR'}</span><h3>${e(job.name)}</h3><p>${e(job.description)}</p>${job.id === view.profession.id ? '<span class="badge">Your livelihood</span>' : offeredAction(ui, actions, job.actionId, `Learn ${job.name.toLowerCase()}`)}</article>`).join('')}</div></details>`;
  const active = view.activeCommission;
  const commissions = active ? `<section class="panel active-commission"><div class="section-heading"><div><span class="eyebrow">A PROMISE TO A CUSTOMER</span><h2>${e(active.goodName)}</h2></div><span class="badge ${active.late ? 'warning' : ''}">${active.late ? 'Overdue' : e(title(active.status))}</span></div><p>For ${e(active.customerName)} · ${e(active.profession)} · ${e(locationName(game, active.locationId))}</p><div class="career-stats">${metric(ui, 'Agreed payment', `${active.pay}g`)}${metric(ui, 'Requested quality', active.targetQuality)}${metric(ui, 'Due', date(active.dueDay))}</div><div class="recipe-materials">${materialNeeds(active.materials)}</div><p class="small-copy">${active.thresholds.exceptional===null?'This older accepted contract retains its original quality and payment terms.':`Target ${active.thresholds.target}; exceptional ${active.thresholds.exceptional} earns a 20% premium on honest or community invoices. More quality above that threshold gives no further payment.`}</p>${active.quality !== null && active.quality !== undefined ? `<p class="commission-quality">Finished quality: <strong>${e(active.quality)} / ${e(active.targetQuality)}</strong></p>` : ''}${actionList(ui, careerActions.filter(action => /^career_make_/.test(action.id) || ['career_invoice', 'career_abandon'].includes(action.id)))}</section>` : view.commissions.length ? `<section><div class="section-heading"><h2>The commission board</h2><span>${e(locationName(game, game.locationId))}</span></div><div class="career-grid commission-grid">${view.commissions.map(offer => `<article class="career-card"><div class="eyebrow">${e(offer.customerName)}</div><h3>${e(offer.goodName)}</h3><p>${e(offer.days)} working days · Requested quality ${e(offer.targetQuality)}</p><div class="recipe-materials">${materialNeeds(offer.materials)}</div><p class="small-copy">Standard method: quality ${offer.quote.quality}; target ${offer.quote.target}; exceptional ${offer.quote.exceptional}. Honest return ${offer.quote.receipt}g − ${offer.quote.fee}g fee − ${offer.quote.materialValue}g ingredients − about ${offer.quote.living}g living = ${offer.quote.netValue}g net value over ${offer.quote.days} days.</p><p class="recipe-time">${e(offer.pay)} gold on delivery · Due ${e(date(offer.dueDay))}</p>${offeredAction(ui, actions, offer.actionId, 'Accept this commission')}</article>`).join('')}</div></section>` : '';
  const shop = view.shop;
  const business = `<section class="panel business-panel"><div class="eyebrow">A DOOR BEARING YOUR NAME</div><h2>${e(shop?.name || 'Your own workplace')}</h2>${shop ? `<p>${e(shop.profession)} · ${e(shop.locationName)}</p><div class="career-stats">${metric(ui, 'Fittings', `Tier ${shop.tier}`)}${metric(ui, 'Weeks opened', shop.weeks)}${metric(ui, 'Gross trade', `${shop.turnover}g`)}</div>${shop.staff.length ? `<div class="career-staff-list">${shop.staff.map(worker => `<article class="career-staff"><div class="heir-heading">${renderAvatar(worker, { size: 'small', age: worker.age })}<div><h3>${e(worker.name)}</h3><small>${e(title(worker.role))} · Age ${e(worker.age)} · ${e(title(worker.status))}</small></div></div><div class="staff-terms"><span>Skill ${e(worker.skill)}</span><span>${e(worker.wage)}g / operating week</span></div></article>`).join('')}</div>` : '<p class="muted">The workbench is yours alone for now. A hired colleague or apprentice will have a name, wages, and a path of their own.</p>'}` : '<p>A lease, reliable work, and a maker’s reputation can turn a livelihood into a place people return to.</p>'}${actionList(ui, businessActions)}</section>`;
  const materialStore = supplies.length ? `<details class="construction-section career-supplies" data-disclosure="career-supplies"><summary>Buy materials from the cooperative</summary><p class="small-copy muted">These supplies are shared with your Workshop, equipment recipes, and commissioned work.</p>${actionList(ui, supplies)}</details>` : '';
  const publicWork = `<section class="panel career-public-works"><div class="eyebrow">A USE FOR WHAT YOU HAVE LEARNED</div><h2>Work that serves your neighbors</h2><p>A difficult craft can become useful care for the place you live. Your own colleagues can share the credit.</p>${offeredAction(ui,actions,'career_public_work')}${view.publicWorks?.length?view.publicWorks.slice().reverse().map(work=>`<article class="legacy-record"><span class="generation-number">${e(work.profession)} · ${e(date(work.day))}</span><h3>${e(title(work.name))}</h3><p>Led by ${e(work.authorName)}${work.colleagueNames.length?` with ${e(work.colleagueNames.join(', '))}`:''} in ${e(locationName(game,work.locationId))}. ${e(work.days)} working days and ${e(work.gold)} gold committed.</p>${button('Find its home','quest-location',work.locationId,'ghost small')}</article>`).join(''):'<p class="muted">Signed community projects will remain in this register when another generation takes up your work.</p>'}</section>`;
  const masterworks = `<section class="panel career-masterworks"><div class="eyebrow">WORK THAT OUTLASTS A SEASON</div><h2>What your hands leave behind</h2>${view.masterworks.length ? view.masterworks.map(work => `<article class="legacy-record"><span class="generation-number">${e(work.profession)} · ${e(date(work.day))}</span><h3>${e(work.name)}</h3><p>Made by ${e(work.authorName)}${work.apprenticeName ? ` with ${e(work.apprenticeName)}` : ''}. Quality ${e(work.quality)}. Kept ${work.recipient === 'community' ? 'by the community' : work.recipient === 'teach' ? 'as a teaching legacy' : 'with the household'} in ${e(locationName(game, work.locationId))}.</p>${button('Find its home', 'quest-location', work.locationId, 'ghost small')}</article>`).join('') : '<p>A lifetime of practice can become a useful object, a teaching record, or a gift kept by the community.</p>'}${offeredAction(ui, actions, 'career_masterwork', 'Begin your lifetime work')}</section>`;
  return `${chapter('Employment', 'Keep a livelihood, attend to a promise, or build a workplace of your own.', 'YOUR WORKING LIFE')}${selectSection(ui,{
    livelihood:`${careerBatchPanel(game,ui)}${summary}${householdBudgetPanel(game,ui)}${renderEconomyPlan(game,ui,options)}${professions}`,
    commissions, business:business+materialStore,
    legacy:`${publicWork}${masterworks}<section class="panel"><h2>Pages from your working life</h2>${historyList(view.history)||'<p>Your working record has yet to be written.</p>'}</section>`
  })}`;
}

export function healthPage(game, ui) {
  const view = healthView(game), { e, chapter, meter, actionCards, historyList, date, button } = ui;
  const actions = getActions(game).filter(action => action.id.startsWith('health_'));
  const recommended = view.suggestionIds.map(id => actions.find(a => a.id === id && !a.disabledReason)).find(Boolean);
  const unavailable = view.suggestionIds.map(id => actions.find(a => a.id === id && a.disabledReason)).find(Boolean);
  const conditionCard = (condition, kind) => `<article class="health-card ${kind} ${condition.careUntil > game.day ? 'recovering' : ''}"><div class="section-heading"><span class="health-kind">${kind === 'physical' ? 'BODILY CARE' : 'EMOTIONAL CARE'}</span><span class="badge">${['', 'Light symptoms', 'Moderate symptoms', 'Demanding symptoms'][condition.severity] || 'Symptoms recorded'}</span></div><h3>${e(condition.name)}</h3><p class="health-since">Since ${e(date(condition.sinceDay))}</p><div class="health-symptoms">${e(condition.symptoms)}</div><p>${e(condition.description)}</p><p class="health-status">${condition.careUntil > game.day ? `Care already supported through ${e(date(condition.careUntil))}` : 'Rest and continuing support are available'}</p><p class="small-copy">${e(condition.progress)}</p></article>`;
  const routines = [['restUntil', 'Rest & recovery'], ['medicineUntil', 'A healer’s care plan'], ['supportUntil', 'Trusted support']].filter(([key]) => view.care[key] > game.day);
  const free = actions.filter(action => !action.cost && action !== recommended), paid = actions.filter(action => action.cost && action !== recommended);
  return chapter('Health & needs',view.summary,'CARE THROUGH LIVED TIME')+selectSection(ui,{
overview:`<section class="panel health-summary" data-health-measures><h2>Two measures of your health</h2><div class="health-grid"><article class="health-card"><h3>Health</h3>${meter(view.combatHp, view.maxCombatHp, 'Health')}<p>${e(view.hpPurpose)}</p></article><article class="health-card"><h3>Bodily wellbeing</h3>${meter(view.bodilyHealth, 100, 'Bodily wellbeing')}<p>${e(view.bodilyPurpose)}</p></article></div><div class="career-stats">${metric(ui, 'Joy', `${view.happiness}/100`)}${metric(ui, 'Stress', `${view.stress}/100`)}</div><p class="small-copy muted">${e(view.risk)}</p>${routines.length ? `<div class="care-routines">${routines.map(([key, label]) => `<div><strong>${e(label)}</strong><span>Through ${e(date(view.care[key]))}</span></div>`).join('')}</div>` : ''}</section><section class="panel care-actions" data-health-next><div class="eyebrow">YOUR CURRENT NEED</div><h2>Where care can help</h2><p>${e(view.concern)}</p>${recommended ? actionCards([recommended]) : game.phase === 'retired' ? '<p>This life’s care and recovery remain in its record.</p>' : `<p class="muted">${e(unavailable?.disabledReason || (game.health.recovery ? 'Continue or end your reserved recovery plan below after resolving any waiting decision.' : 'Finish the waiting moment before starting another care session.'))}</p>${button('Return to your life', 'tab', 'life', 'secondary')}`}</section>`,
conditions:`<section><div class="section-heading"><h2>The body’s needs</h2><span>${view.physical.length ? `${view.physical.length} active` : 'No active symptoms recorded'}</span></div>${view.physical.length ? `<div class="health-grid">${view.physical.map(condition => conditionCard(condition, 'physical')).join('')}</div>` : '<div class="care-support">No ongoing physical condition is recorded. Rest and a gentle routine can still be part of your days.</div>'}</section><section><div class="section-heading"><h2>Emotional wellbeing</h2><span>${view.mental.length ? `${view.mental.length} active` : 'No active symptoms recorded'}</span></div>${view.mental.length ? `<div class="health-grid">${view.mental.map(condition => conditionCard(condition, 'mental')).join('')}</div>` : '<div class="care-support">No ongoing emotional condition is recorded. You can seek company and support without needing a diagnosis.</div>'}</section>`,
care:`${free.length ? `<section class="panel care-actions"><div class="eyebrow">CARE WITHIN REACH</div><h2>Free rest &amp; support</h2>${actionCards(free)}</section>` : ''}${paid.length ? `<section class="panel care-actions"><h2>A healer’s review</h2>${actionCards(paid)}</section>` : ''}${!actions.length && game.phase === 'retired' ? `<section class="panel">${button('Read the family’s next chapter', 'tab', 'legacy', 'secondary')}</section>` : ''}`,
history:`<section class="panel health-history"><h2>Your care record</h2>${historyList(view.history) || '<p class="muted">Care, symptoms, support, and recovery will be remembered here.</p>'}</section>`
  });
}

export function legacyPage(game, ui) {
  const view = lineageView(game), { e, title, button, chapter, meter, paragraphs, date, historyList } = ui;
  const actions = getActions(game);
  const childActions = new Set(view.children.flatMap(child => ['nurture', 'school', 'lesson', 'heir', 'continue', 'future', 'independence'].map(kind => `lineage_${kind}_${child.id}`)));
  const familyActions = actions.filter(action => action.id === 'life_family' || action.id === 'lineage_marry' || action.id.startsWith('life_home_'));
  const remembrances = actions.filter(action => action.id.startsWith('lineage_mourn_'));
  const partner = view.partner;
  const household = `<section class="panel legacy-household"><div class="eyebrow">THE LIFE AROUND YOUR HEARTH</div><h2>${partner ? e(partner.status) : view.widowed ? 'A shared life remembered' : 'A household of your own'}</h2>${partner ? `<div class="heir-heading">${renderAvatar(game.life.people.find(person => person.id === partner.id) || partner, { size: 'small' })}<div><h3>${e(partner.name)}</h3><small>${e(partner.status)}</small></div></div>${meter(partner.bond, 100, 'Your bond')}${button('Talk together', 'show-contact', partner.id, 'secondary small')}` : `<p>${view.widowed ? 'Your partner’s name and the years you shared remain in the family record.' : 'Friendship can grow into a shared household. A single parent can also offer a child a permanent home.'}</p>${button('Spend time with people', 'tab', 'relationships', 'secondary small')}`}<div class="inheritance-list"><div><span>Home</span><strong>${e(title(game.life.home.tier))}</strong></div><div><span>Household savings</span><strong>${e(game.hero.gold)}g</strong></div><div><span>Living children</span><strong>${view.children.filter(living).length}</strong></div>${game.careers?.shop ? `<div><span>Workplace</span><strong>${e(game.careers.shop.name)}</strong></div>` : ''}</div>${actionList(ui, familyActions)}</section>`;
  const children = `<section><div class="section-heading"><h2>The children you raise</h2><span>${view.children.filter(living).length} living</span></div>${view.children.length ? `<div class="heir-grid">${view.children.map(child => {
    const record = game.lineage?.people.find(person => person.source === 'child' && person.localId === child.id);
    const development = child.development, education = development.education;
    const ownActions = actions.filter(action => childActions.has(action.id) && ['nurture', 'school', 'lesson', 'heir', 'continue', 'future', 'independence'].some(kind => action.id === `lineage_${kind}_${child.id}`));
    return `<article class="heir-card ${child.preferred ? 'eligible preferred' : ''} ${!living(child) ? 'deceased' : ''}"><div class="heir-heading">${renderAvatar({ ...child, appearance: record?.appearance }, { size: 'small', age: child.age })}<div><h3>${e(child.name)}</h3><small>${living(child) ? `Age ${e(child.age)}` : 'Remembered in the family'}</small></div></div><div class="badge-row">${child.preferred ? '<span class="badge">Preferred successor</span>' : ''}${record?.adopted === true ? '<span class="badge">Adopted</span>' : ''}</div><div class="child-traits">${Object.entries(development.traits).map(([label, value]) => `<div><span>${e(title(label))}</span><strong>${e(value)}</strong></div>`).join('')}</div><p>${education.route ? `${e(title(education.route === 'public' ? 'community' : education.route))} schooling · ${e(education.attendance)} attended sessions` : 'Their learning route is still open.'}</p>${education.qualifications.length ? `<div class="badge-row">${education.qualifications.map(qualification => `<span class="badge">${e(qualification.label)}</span>`).join('')}</div>` : ''}${child.adultLife?`<section class="child-adult-life"><h4>${e(child.adultLife.title)}</h4><p>${e(child.adultLife.summary)}</p><p class="small-copy">${e(child.adultLife.progress)} ${e(child.adultLife.residence)}</p><p class="small-copy muted">${e(child.adultLife.support)}</p></section>`:''}<div class="child-skills">${Object.entries(development.skills).filter(([, value]) => value > 0).map(([name, value]) => `<span>${e(title(name))} <strong>${e(value)}</strong></span>`).join('') || '<span>Practiced skills will be recorded here.</span>'}</div>${living(child) ? `<p class="small-copy muted">About ${e(child.inheritance)} gold from current savings would pass to ${e(child.name)}, before the final household costs are settled.</p>` : ''}${actionList(ui, ownActions)}${development.history.length ? `<details class="construction-section child-learning-record" data-disclosure="child-lessons-${e(child.id)}"><summary>Their own remembered lessons</summary>${historyList(development.history)}</details>` : ''}</article>`;
  }).join('')}</div>` : '<section class="panel"><p>No child is recorded in your household yet. Shared life, housing, and the time you make for care can open that next chapter.</p></section>'}</section>`;
  const continuation = `<section class="panel legacy-continuation"><div class="eyebrow">THE NEXT LEAF OF THE BOOK</div><h2>${game.phase === 'retired' ? view.heroDeath ? 'A life remembered. A story continuing.' : 'Your later years, their beginning.' : 'A future you can prepare for'}</h2><p>${game.phase === 'retired' ? view.children.some(living) ? 'Choose a living child above to carry the story forward at their own age, with their own learning. The world keeps its calendar and the places your family changed.' : 'There is no living child in this family record to take up the next chapter. This life still has its chronicle.' : 'Naming a preferred successor records your hopes. When you close this chapter, you can choose a living child; they keep their own recorded skills, education and adult livelihood.'}</p><p class="small-copy muted">Living children share the household savings. The chosen successor receives its home, equipment, completed structures, and recorded workplace.</p>${offeredAction(ui, actions, 'retire', 'Close this chapter of your life')}${game.phase === 'retired' && game.chronicle ? `<details class="construction-section"><summary>Read ${e(game.hero.name)}’s chronicle</summary><div class="legacy-chronicle">${paragraphs(game.chronicle)}</div></details>` : ''}</section>`;
  const past = `<section class="panel dynasty-record"><div class="eyebrow">THE FAMILY BOOK</div><h2>Earlier generations</h2><div class="lineage-list">${view.history.length ? view.history.map(record => `<article class="generation-card"><span class="generation-number">GENERATION ${e(record.generation)} · ${record.reason === 'death' ? 'A LIFE REMEMBERED' : 'RETIRED'}</span><h3>${e(record.name)}</h3><p>Age ${e(record.age)} · ${e(date(record.endedDay))}${record.cause ? `<br>${e(record.cause)}` : ''}</p>${record.inheritance ? `<p class="small-copy muted">${e(record.inheritance.gold)} gold passed to the chosen child. ${e(title(record.inheritance.homeTier))} and the household’s recorded property continued with them.</p>` : ''}${record.chronicle ? `<details class="construction-section"><summary>Read this life’s chronicle</summary><div class="legacy-chronicle">${paragraphs(record.chronicle)}</div></details>` : ''}</article>`).join('') : '<p class="muted">You are writing this family’s first recorded chapter.</p>'}</div></section>`;
  const remembered = view.deceased.length ? `<section class="panel remembered-family"><h2>Names kept by the living</h2>${view.deceased.map(person => `<article class="legacy-record"><h3>${e(person.name)}</h3><p>${person.age === null ? 'Age unrecorded' : `Age ${e(person.age)}`} · ${person.day === null ? 'Date unrecorded' : e(date(person.day))}</p></article>`).join('')}${actionList(ui, remembrances)}</section>` : '';
  const earlierPeople = view.relatives?.length ? `<section class="panel earlier-family"><h2>People from an earlier chapter</h2>${view.relatives.map(person => `<article class="remembered-entry"><strong>${e(person.name)}</strong>${person.bornDay === null ? '' : `<small>Age ${e(Math.max(0, Math.floor((game.day - person.bornDay) / 365)))}</small>`}</article>`).join('')}</section>` : '';
  return chapter('Family & legacy','The household you share, the children you raise, and the lives that follow.','THE FAMILY BOOK')+selectSection(ui,{
   family:household+householdBudgetPanel(game,ui), children, succession:continuation,
   history:`${past}${view.unrecordedParents?.length?`<section class="panel unrecorded-parentage"><h2>Unrecorded family ties</h2><p>Their identities or whereabouts remain unknown. The family book records no confirmed deaths for these ties.</p>${view.unrecordedParents.map(p=>`<p><strong>${e(p.name)}</strong> · ${e(p.status)}</p>`).join('')}</section>`:''}${remembered}${earlierPeople}`
  });
}
